	var en_default$1 = {
		"v 1.8.0:0": ["Added user data analytics on profile pages: a summary, rating heatmap, monthly and hourly activity, multi-user rating and contest rank curve comparison, rating and tag distributions, tag weak spots, recent average rating, attempts, verdicts, contest pace, participation types, languages and unsolved problems.", "Added three items to the roadmap: full internationalization (i18n), improved contest analysis & prediction, and built-in translation."],
		"v 1.8.0:1": [
			"Improved the display of non-square avatars in the rating analysis dialog.",
			"The number of contests cached for rating prediction can now be customized, 10 by default.",
			"To help users try new features, many options are now enabled by default, and some default values were adjusted.",
			"Reorganized the storage structure of the plugin configuration by menu tab; existing settings will be migrated automatically.",
			"Updated the acknowledged projects and redesigned the Acknowledgments page around the petal theme.",
			"Improved the styling of some submenu components (sub-options, sliders and roadmap cards).",
			"Times shown in tooltips of the original page now follow the custom time format.",
			"Added a TypeScript language icon, and languages without a preset icon now show a common unknown-language icon.",
			"Rating prediction now shows staged progress while loading: standings, ratings, submissions and calculation.",
			"Previews of large data in the storage viewer are trimmed further, making it smoother to switch between items.",
			"Added a notice explaining that dark themes from other extensions are no longer adapted for."
		],
		"v 1.8.0:2": [
			"Fixed incomplete solved-problem records for accounts with more than 10,000 submissions.",
			"Fixed setting changes being overwritten by other pages when several pages are open at once.",
			"Fixed leftover time text appearing in other tooltips after hovering a time on the page.",
			"Fixed the deprecated cache listing other scripts' data, and data left in the site's local storage by early versions not being clearable."
		],
		"v 1.7.0:0": ["Added contest rating prediction with rating changes, performance, rank progression and single-user rating analysis, plus a shortcut to toggle it.", "Added rated/unrated/virtual participant tags indicating how each participant takes part in the contest."],
		"v 1.7.0:1": [
			"Improved the storage structure of the storage categories and the labelling of displayed fields.",
			"Replaced the userscript icon with the Colorforces logo.",
			"Improved and expanded contest-page time-format styling compatibility.",
			"With help from Claude, redesigned and refined the UI of the menu and some pages.",
			"Reorganized the code directory structure and added unit tests."
		],
		"v 1.7.0:2": ["Fixed dialogs closing when a text selection drag ended outside the dialog.", "Fixed several cases of interface jitter, misalignment, and text not following language changes."],
		"v 1.6.0:0": [
			"With help from Codex, decoupled and standardized the project structure and component organization, adding extensive concise Chinese function-level comments to improve readability and maintainability.",
			"Further polished the menu interface.",
			"Added transitions for page feature changes and settings-panel interactions.",
			"Improved compatibility with native Codeforces styles.",
			"Separated plugin runtime data from preferences.",
			"Bundled the menu title font to avoid reliance on remote font loading.",
			"Moved distribution and updates to Releases, automated publishing, and retained the legacy update entry.",
			"Added a separate solved-row highlighting toggle, with shortcuts for highlighting and menu language switching.",
			"Improved real-time verdict abbreviations and extended them to submission history on problem pages.",
			"Moved the algorithm-tag visibility settings to Appearance.",
			"Users can customize the settings panel size and position, with drag-to-adjust support."
		],
		"v 1.6.0:1": [
			"Explicitly request the official problemset in English and refresh older-language caches.",
			"Fixed menu selection indicator misalignment when moving between displays with different scaling levels.",
			"Fixed middle-click opening of menu links in new tabs."
		],
		"v 1.5.9:0": ["Added automatic update detection functionality."],
		"v 1.5.9:1": ["Optimized the storage management interface UI and related logic."],
		"v 1.5.9:2": [
			"Fixed missing difficulty ratings for shared problems across concurrent contests (e.g., Div.1 and Div.2) in official Codeforces data by grouping parallel contests by start time and inheriting ratings from peer contests with matching problem names.",
			"Fixed an issue where the AC background color picker in settings displayed as pure black.",
			"Fixed an issue where blog and topic post author avatars were not displayed."
		],
		"v 1.5.8:0": [
			"Added sub-options to \"Hide Algorithm Tags\" for hiding difficulty rating tags and retaining tags for AC problems.",
			"Optimized the color display for 2100~2300 and 2300~2400 rating problems under the \"Tag\" style to improve visual distinction.",
			"Optimized UI presentation across various interfaces."
		],
		"v 1.5.7:0": [
			"Integrated the third-party [CList](https://clist.by) problem dataset, supporting fine-grained problem ratings with both Cookie session and API Key authentication modes.",
			"Added a dedicated \"Shortcuts\" settings panel, allowing users to customize global hotkeys for frequent actions, with key combination recording, conflict detection, and one-click reset.",
			"Added a dedicated \"Storage\" management panel to visualize Tampermonkey script storage usage, inspect and copy cached data JSON, and selectively clear caches or restore factory defaults.",
			"Added a dedicated \"Changelog\" page with built-in version history and collapsible cards, providing an intuitive overview of all release details.",
			"Added a dedicated \"Roadmap\" page to outline upcoming feature milestones, development progress, and open channels for community feature proposals.",
			"Added a dedicated \"Acknowledgments\" page, honoring pioneering open-source projects including [CF-Helper](https://chromewebstore.google.com/detail/codeforces-helper/ahoeafmlmoohkkalcickdnkifpfnolpj), [CList](https://clist.by), [OJ Better](https://github.com/beijixiaohu/OJBetter), and [Carrot-Plus](https://github.com/wuyuqian114514/carrot-plus)."
		],
		"v 1.5.7:1": [
			"Polished the settings menu UI with more refined sub-menu groupings.",
			"Migrated storage from browser LocalStorage to Tampermonkey script storage, avoiding potential LocalStorage 5MB quota limits.",
			"Added a \"Fill Table Cells with Tag Style\" option under the Tag display style, offering softer-toned rating cell presentations.",
			"Expanded format token support for custom time templates and provided detailed built-in documentation.",
			"Provided detailed built-in reference documentation for verdict status abbreviations.",
			"Migrated the relevant display logic of team information to status and submission pages.",
			"Restructured the changelog documentation for clearer categorization and readability."
		],
		"v 1.5.7:2": ["Resolved an issue where some user avatar images failed to load following Codeforces' recent server maintenance, adding automatic proxy path adaptation and fallback self-healing.", "Fixed an issue where placing the Rating column as the first column on problemset and contest pages prevented the [Competitive Companion](https://chromewebstore.google.com/detail/Competitive%20Companion/cjnmckjndlpiamhfimnnjmnckgghkjbl) extension from parsing all problems with one click."],
		"v 1.5.6:0": ["Added a \"Hide Algorithm Tags\" option in General settings, allowing users to conceal specific algorithm tags on problem pages while retaining the problem difficulty score."],
		"v 1.5.6:1": [
			"Improved the formatting and layout of Ghost Participant teams in regional ICPC standings when both \"User Avatars\" and \"Format Teams\" are enabled.",
			"Upgraded the settings menu UI with a multi-tab grouped navigation layout (General, Appearance, Ratings, Users) for a cleaner and more intuitive configuration experience.",
			"Added a master switch for \"Colored Ratings\" in the Ratings settings tab, allowing users to toggle all rating colorizations and displays across the site with a single click."
		],
		"v 1.5.5:0": ["This project is migrated from [CF-Submissions-Ratings (CFSR)](https://github.com/GodExious/CF-Submissions-Ratings) v1.5.5 and has been rebranded as Colorforces. All future feature developments and updates will be built upon this version in this new repository."],
		"v 1.5.5:1": ["Added real-time UI preview for the settings menu. Visual changes are now immediately reflected on the page without needing a refresh."],
		"v 1.5.5:2": ["Slightly beautified the settings menu UI and added project links and a quick feedback channel to the footer.", "Applied optional time formatting to the start time of virtual contests as well."],
		"v 1.5.4:0": ["Resolved the issue on the Standings page where long team names were truncated/obscured when avatars were enabled. Added a new \"Format Teams\" feature toggle in the settings for both Ghost Participants and standard CF teams."],
		"v 1.5.4:1": ["Fixed the display of writers' avatars on the Contest page when avatars were enabled, restoring a clean, line-by-line layout."],
		"v 1.5.3:0": ["Fixed a Flash of Unstyled Content (FOUC) issue where the color picker (Pickr) would briefly flash upon page load before its external CSS was fully downloaded."],
		"v 1.5.2:0": ["Mapped Node.js and Delphi to their respective language icons correctly."],
		"v 1.5.2:1": [
			"Fixed an issue where injected avatars in non-data tables (like the Recent Actions page) could be pushed to the line above due to text wrapping or incorrect table layout detection.",
			"Prevented redundant avatar rendering on Codeforces profile pages and near native large avatar containers to maintain a clean UI.",
			"Fixed an issue where the C language variants (e.g., \"C11\") and the D language were missing icons in the submission status table. Added custom SVG icons for C (Green) and D."
		],
		"v 1.5.1:0": [
			"Support toggling the difficulty rating display style in the settings panel (Classic \"Block\" / iView-style \"Tag\").",
			"Added toggles in the settings panel to control the display of ratings in different areas (Submissions, Status, Hacks, ProblemSet, Contest Problems, Standings, Problem Tags).",
			"Support enabling and customizing time format strings with real-time preview.",
			"Added support for displaying user avatars in tables, with customizable size via settings.",
			"Added support for displaying dedicated language icons (e.g., C++, Python, Go) in the language column, with customizable size.",
			"Added support for minimalist abbreviations of verdict statuses (e.g., `Accepted` -> `AC`, `Time limit exceeded` -> `TLE`)."
		],
		"v 1.5.1:1": [
			"Completely removed the redundant logic of appending `[xxxx]` score text next to problem links on normal pages.",
			"Resolved layout issues in the time column when custom time formatting is disabled, fully restoring the official default style.",
			"Resolved an issue where difficulty background highlights were glaring when using dark background plugins (such as Dark Reader, CF-Better)."
		],
		"v 1.5.0:0": ["Added a floating \"Settings\" menu at the bottom right corner of the page.", "Added support for customizing the AC (Accepted) background color via the settings menu, with configuration persisted locally."],
		"v 1.4.2:0": ["Optimized text readability for higher ratings. For problem ratings `>= 1600` (Blue tier and above), the font color now automatically switches to high-contrast white (`#FFFFFF`)."],
		"v 1.4.1:0": ["Changed the time formatting from `yyyy-mm-dd hh:mm` to `yyyy/mm/dd hh:mm` for better readability."],
		"v 1.4.0:0": ["Added problem rating color display to problem tags."],
		"v 1.4.0:1": [
			"Optimized difficulty rating and AC status display on contest pages.",
			"Optimized difficulty rating display on hacks pages.",
			"Optimized time formatting and table layout on submissions/status pages."
		],
		"v 1.3.5:0": ["Displays problem difficulty ratings directly on `submissions` and `status` pages, complete with corresponding color highlighting."],
		"v 1.3.5:1": ["Fetches problem data via the official Codeforces API and updates locally only once per day, avoiding excessive network requests."]
	};
	var zh_default$1 = {
		"v 1.8.0:0": ["新增用户数据图表分析，在个人主页展示统计摘要、难度热力图、月度活跃度、刷题作息、多用户评级曲线与参赛排名曲线对比、难度与标签分布、标签弱项、近期平均难度、尝试次数、提交结果、比赛速度、参赛类型、语言分布和未解决题目。", "开发计划新增三项：完善多语言支持、完善比赛分析预测功能、内置翻译功能。"],
		"v 1.8.0:1": [
			"优化了评级分析弹窗中非正方形头像的显示。",
			"比赛评分预测缓存的比赛场数支持自定义，默认 10 场。",
			"为了让用户更好地体验新功能，许多配置的默认值设置为开启，并调整了部分设置的默认值。",
			"优化了插件配置的存储结构，按菜单页签归档，原有设置将自动迁移。",
			"更新致谢项目，并以花瓣为主题重新设计了致谢页。",
			"优化了子菜单部分组件（子选项、滑动条、开发计划卡片）的样式。",
			"悬停提示里的原站时间也按设置的时间格式显示。",
			"新增了 TypeScript 的语言图标，并为没有预设图标的语言统一显示未知语言图标。",
			"比赛评分预测加载时显示分段进度：榜单、评级数据、提交记录、计算。",
			"优化了存储查看器对大规模数据的预览截断，切换查看更流畅。",
			"增加了关于不再适配其他插件深色主题样式的说明提示。"
		],
		"v 1.8.0:2": [
			"修复提交数超过一万的账号，已通过题目记录不完整的问题。",
			"修复同时打开多个页面时，设置修改可能被其他页面覆盖的问题。",
			"修复悬停查看原站时间后，其他悬停提示里残留时间文字的问题。",
			"修复「已弃用的缓存」误列其他脚本的数据，以及早期版本留在网站本地存储里的数据无法清理的问题。"
		],
		"v 1.7.0:0": ["新增比赛评分预测，支持涨跌分、表现分、等级变化，以及单用户评级分析的功能，并提供一键开关快捷键。", "新增选手标签 rated/unrated/virtual，标注参赛选手的参赛类型。"],
		"v 1.7.0:1": [
			"优化了存储分类的存储结构和展示字段标注。",
			"用户脚本图标改用 Colorforces Logo.",
			"优化并拓展了竞赛页面的时间格式化样式兼容。",
			"在 Claude 的帮助下，重新优化设计了菜单和部分页面的 UI.",
			"整理代码目录结构，并补充单元测试。"
		],
		"v 1.7.0:2": ["修复在弹窗内拖选文字到弹窗外松开时，弹窗被关闭的问题。", "修复若干界面抖动、错位与不随语言切换的问题。"],
		"v 1.6.0:0": [
			"在 Codex 的帮助下，对项目进行解耦与规范化重构，整理组件分类与目录，并补充大量函数级中文注释，提高代码可读性与可维护性。",
			"进一步美化菜单界面。",
			"为页面功能变化和设置面板交互增加过渡动画。",
			"优化了对 Codeforces 原始样式的兼容。",
			"将插件运行数据从偏好配置中独立整理。",
			"内置菜单标题字体，避免远程字体加载影响显示。",
			"改用 Release 发布与更新，增加自动发布流程，并保留旧版兼容入口。",
			"为已 AC 题目的整行高亮增加独立开关，并为其及菜单语言切换新增快捷键。",
			"优化了判题状态的实时缩写，并支持题目页的提交历史。",
			"调整了隐藏算法标签功能的分类。",
			"用户可以自定义设置面板大小及位置，并支持拖动调整。"
		],
		"v 1.6.0:1": [
			"固定使用英文获取官方题库，并兼容刷新旧语言缓存。",
			"修复在不同缩放倍率的显示器间切换时，菜单选中标签错位的问题。",
			"修复菜单链接无法使用鼠标中键在新标签页打开的问题。"
		],
		"v 1.5.9:0": ["新增了自动更新检测功能。"],
		"v 1.5.9:1": ["优化了存储界面的UI和相关逻辑。"],
		"v 1.5.9:2": [
			"修复了 CF 官方数据中多场并赛（如 Div.1 与 Div.2 并行场次）重合题目在部分场次缺失难度分的问题，通过比赛开始时间关联同组并赛场次并自动承接同名题目的难度评分。",
			"修复了设置页中 AC 背景色的颜色选择器显示为纯黑的问题。",
			"修复了博客和主页帖子中发布者头像未正常显示的问题。"
		],
		"v 1.5.8:0": [
			"为“隐藏算法标签”功能增加了“隐藏难度分标签”和“不隐藏已AC题目标签”的子项。",
			"优化了“标签”样式下 2100~2300 以及 2300~2400 分橙题的颜色显示，提升视觉区分度。",
			"优化了部分界面的 UI 表现。"
		],
		"v 1.5.7:0": [
			"接入第三方 [CList](https://clist.by) 题目数据源，支持展示更加精细的题目难度评分，并提供 Cookie 会话与 API Key 两种认证同步模式。",
			"“快捷键”设置面板，支持为常用功能自定义全局快捷热键，包含按键录制、冲突检测与一键重置功能。",
			"“存储”管理面板，可视化展示油猴脚本存储占用分布，支持分项查看缓存数据、一键复制、独立清理或重置出厂配置。",
			"“更新日志”页面，内置各历史版本的演进记录与折叠卡片交互，直观展示每一次版本更新的具体细节。",
			"“开发计划”页面，展示插件后续功能的演进路线与开发进展规划，并提供社区功能提议通道，共同见证插件成长。",
			"“致谢”页面，向 [CF-Helper](https://chromewebstore.google.com/detail/codeforces-helper/ahoeafmlmoohkkalcickdnkifpfnolpj)、[CList](https://clist.by)、[OJ Better](https://github.com/beijixiaohu/OJBetter)、[Carrot-Plus](https://github.com/wuyuqian114514/carrot-plus) 等开源先驱与社区项目致敬。"
		],
		"v 1.5.7:1": [
			"优化了菜单的 UI 界面，提供了更为精细的子菜单分组。",
			"将原有的 LocalStorage 存储方式改为油猴脚本存储方式，避免可能超过 LocalStorage 潜在的 5MB 上限。",
			"在难度分“标签”展示样式下新增“表格内标签铺满单元格”选项，提供更轻柔色系的难度分单元格展示。",
			"为时间格式化模板字符串提供了更多格式字符串的支持和详细的内置文档介绍。",
			"为判题状态缩写提供了详细的内置速查文档。",
			"将队伍信息的相关展示逻辑，迁移到了 status 和 submissions 等页面。",
			"优化了更新日志的文档结构。"
		],
		"v 1.5.7:2": ["修复了 Codeforces 官方近期维护后导致读取的部分用户头像不可用的问题，增加了反代路径自动适配与加载失败自愈降级机制。", "修复了在题单页和比赛题单页第一列使用 Rating 列导致 [Competitive Companion](https://chromewebstore.google.com/detail/Competitive%20Companion/cjnmckjndlpiamhfimnnjmnckgghkjbl) 插件无法一键读取题单题目的问题。"],
		"v 1.5.6:0": ["新增了“隐藏算法标签”功能，支持隐藏题目页右侧具体的算法 Tag，仅保留难度评分。"],
		"v 1.5.6:1": [
			"优化了部分 ICPC 区域赛榜单在开启“显示用户头像”和“队伍信息格式化”时，Ghost Participant 队伍名称与成员信息的排版样式。",
			"升级了插件设置菜单 UI，引入分组导航（通用、界面、难度分、用户），使选项结构更加清晰易用。",
			"在“难度分”设置中增加了“色彩展示难度分”总开关，支持一键开启或关闭全站难度分着色与展示。"
		],
		"v 1.5.5:0": ["本项目从 [CF-Submissions-Ratings (CFSR)](https://github.com/GodExious/CF-Submissions-Ratings) v1.5.5 迁移并更名而来，作为 Colorforces 的初代 v1.5.5 版本。后续的所有功能开发与维护都将在此版本基础上继续进行。"],
		"v 1.5.5:1": ["实时界面预览。当在设置菜单改变样式选择时，页面将实时反映展示效果。"],
		"v 1.5.5:2": ["轻微美化了设置菜单的 UI，在底部增设了项目链接和快速反馈通道。", "将虚拟竞赛的开始时间也一并纳入了可选的时间格式化范围。"],
		"v 1.5.4:0": ["解决了 Standings 页面中开启头像显示后长队名展示被截断/遮挡的问题，并在设置中提供了队伍（包括 Ghost Participant 和 CF Team）格式化展示的功能选项。"],
		"v 1.5.4:1": ["修复了 Contest 页面中开启头像显示后编写者头像的展示问题，现已恢复为美观的单行独立展示。"],
		"v 1.5.3:0": ["修复了页面首次加载时，颜色选择器（Pickr）由于外部 CSS 异步加载较慢而导致的未样式化内容闪烁（FOUC）问题。"],
		"v 1.5.2:0": ["完善了 Node.js 以及 Delphi 的语言图标映射。"],
		"v 1.5.2:1": [
			"修复了在非数据表格（如 Recent Actions 动态页面）中，由于文本换行或表格布局误判导致头像被挤到上一行的问题。",
			"移除了个人主页等带有 Codeforces 原生大头像框区域的冗余小头像，保持 UI 简洁。",
			"修复了提交状态表格中 C 语言（如 \"C11\" 等版本）和 D 语言缺失专属图标的问题，并补充了自定义的 C（绿色）和 D 语言 SVG 矢量图标。"
		],
		"v 1.5.1:0": [
			"支持在设置面板中自由切换难度分呈现样式（经典“色块” / iView 风格“标签”）。",
			"支持在设置面板中通过开关控制难度分在不同区域（提交、状态、Hack、各大题单、榜单及题目页标签）的显示。",
			"支持开启并自定义时间格式化字符串，自带实时预览。",
			"支持在表格中显示用户头像，并在设置中支持自定义大小。",
			"支持在语言列显示语言专属图标（如 C++、Python、Go 等），并支持自定义图标大小。",
			"支持将判题状态进行极简缩写（如 `Accepted` -> `AC`, `Time limit exceeded` -> `TLE` 等）。"
		],
		"v 1.5.1:1": [
			"彻底删除了在普通页面题目链接旁附加 `[xxxx]` 分数文本显示的冗余逻辑。",
			"修复了关闭自定义时间格式时，表格时间列排版错乱的问题，完全恢复官方默认样式。",
			"修复了在使用深色背景插件（如 Dark Reader、CF-Better）时，难度分高亮背景刺眼的问题。"
		],
		"v 1.5.0:0": ["新增页面右下角悬浮的“插件设置”菜单。", "允许用户在设置中自定义 AC（Accepted）记录的背景色，配置将保存在本地缓存。"],
		"v 1.4.2:0": ["优化了高分段的视觉可读性。现在，对于分数 `>= 1600`（即蓝色及以上的段位），难度分的字体颜色会自动切换为高对比度的纯白色 (`#FFFFFF`)。"],
		"v 1.4.1:0": ["更改了时间格式，从 `yyyy-mm-dd hh:mm` 切换为 `yyyy/mm/dd hh:mm`，使其更加直观。"],
		"v 1.4.0:0": ["在 Problem 页面的 Tag 增加了题目 Rating 颜色显示。"],
		"v 1.4.0:1": [
			"优化了 Contest 页面的难度分展示与 AC 状态展示。",
			"优化了 Hacks 页面的难度分展示。",
			"优化了 Submissions/Status 页面的时间格式化和表格布局。"
		],
		"v 1.3.5:0": ["在 `submissions` 页面和 `status` 页面直接显示题目的难度分数，并根据难度带有相应的色彩高亮。"],
		"v 1.3.5:1": ["题目分数数据通过 Codeforces 官方 API 获取，每天仅在本地更新一次缓存，避免发送过多的网络请求。"]
	};
